//! `latest_project_scan` cases. The `prepare_project` cases need the
//! tool-injecting preparation runner — a missing projects API, deferred in
//! `oracle/deferred-tests.toml`. The streamed-report case is the mcp slice.
//!
//! The `scans/*.sqlite` fixtures are generated by the reference suite
//! via the oracle's own `_saved_scan` pipeline.

#[path = "common/testkit.rs"]
mod testkit;

use spiderhead_projects::runtime::latest_project_scan;

fn saved_scan(root: &std::path::Path, fixture: &str, name: &str) {
    std::fs::create_dir_all(root.join("scans")).expect("scans dir");
    std::fs::copy(testkit::fixture(fixture), root.join("scans").join(name)).expect("scan");
}

#[test]
fn latest_project_scan_is_the_newest_complete_audited_scan() {
    let (_dir, root) = testkit::project("prepare", "latest");
    saved_scan(&root, "audited-cap50-stopped.sqlite", "partial.sqlite");
    saved_scan(&root, "audited-cap500.sqlite", "full.sqlite");

    let latest = latest_project_scan(&root).expect("latest_project_scan");
    assert_eq!(latest.file_name().unwrap(), "full.sqlite");
}

#[test]
fn latest_project_scan_refuses_when_no_complete_scan_exists() {
    let (_dir, root) = testkit::project("prepare", "none");

    let err = latest_project_scan(&root).expect_err("must refuse");
    assert!(
        err.to_string().contains("no finished, audited scan"),
        "got: {err}"
    );
}
